"""Step 3: Add action info text columns to task table + backfill data."""
import sys, time
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from app.clients.feishu import FeishuClient
from app.config import get_settings

settings = get_settings()
client = FeishuClient(settings)
app_token = settings.feishu_bitable_app_token
task_table = settings.feishu_table_tasks
action_table = settings.feishu_table_actions

# Columns to add: { task_table_column_name: action_table_source_field }
ACTION_COPY_COLUMNS = {
    "动作-闭环状态": "闭环状态",
    "动作-原因": "原因",
    "动作-采取动作": "采取动作",
    "动作-是否有效": "是否有效",
    "动作-复查日期": "复查日期",
}

# ── Step 1: Ensure columns exist ──
task_fields = client.list_fields(app_token, task_table)
existing_names = {f["field_name"] for f in task_fields}
print(f"Existing task columns ({len(existing_names)}): {sorted(existing_names)}")

to_create = [name for name in ACTION_COPY_COLUMNS if name not in existing_names]
print(f"\nColumns to create: {to_create}")

for name in to_create:
    try:
        resp = client.create_field(app_token, task_table, name, 1)  # type 1 = text
        print(f"  Created [{name}]: {resp.get('field',{}).get('field_id','?')}")
    except Exception as e:
        print(f"  ERROR creating [{name}]: {e}")
    time.sleep(0.2)

# ── Step 2: Build action data map (关联异常编号 -> fields) ──
print("\nReading action records...")
action_data = {}  # key (关联异常编号) -> {field_name: value}
for item in client.iter_records(app_token, action_table, page_size=100):
    rid = item.get("record_id")
    fields = item.get("fields") or {}
    key = str(fields.get("关联异常编号") or "").strip()
    if key:
        action_data[key] = {
            "record_id": rid,
            "fields": fields,
        }
print(f"  {len(action_data)} action records")

# ── Step 3: Backfill task records ──
print("Backfilling task records...")
to_update = []
updated = 0
for item in client.iter_records(app_token, task_table, page_size=100):
    rid = item.get("record_id")
    fields = item.get("fields") or {}
    task_no = str(fields.get("异常编号") or "").strip()
    if not task_no or not rid:
        continue

    action = action_data.get(task_no)
    if not action:
        continue

    update_fields = {}
    for task_col, action_col in ACTION_COPY_COLUMNS.items():
        existing_val = fields.get(task_col)
        action_val = action["fields"].get(action_col)

        # Only update if action has data and task column is empty or different
        if action_val is not None and action_val != "" and existing_val != action_val:
            update_fields[task_col] = action_val

    if update_fields:
        to_update.append({"record_id": rid, "fields": update_fields})
        updated += 1

print(f"  Records to update: {updated}")

if to_update:
    for i in range(0, len(to_update), 100):
        chunk = to_update[i : i + 100]
        client.bitable_batch_update(app_token, task_table, chunk)
        print(f"  Batch {min(i + 100, len(to_update))}/{len(to_update)} done")
        time.sleep(0.3)
    print(f"\nDONE: Updated {len(to_update)} task records with action info")
else:
    print("All records already have latest action data.")

